"""Rubine Chat API – every assistant message is generated by the selected model."""
from __future__ import annotations

import asyncio
import json
import threading
import time
from typing import AsyncIterator

from fastapi import APIRouter, Depends, HTTPException, Request
from fastapi.responses import StreamingResponse
from pydantic import BaseModel, Field
from sqlalchemy import delete, func, or_, select
from sqlalchemy.orm import Session

from ..db import iso, Conversation, Example, Message, ModelVersion, get_db, session_scope, utcnow
from ..llm import registry
from ..llm.engine import EngineUnavailable, get_engine
from ..security.auth import require_auth
from ..training import data as data_mod

router = APIRouter(prefix="/api/chat", dependencies=[Depends(require_auth)])


class NewConversation(BaseModel):
    title: str | None = Field(default=None, max_length=200)
    model_version_id: str | None = None


class PatchConversation(BaseModel):
    title: str | None = Field(default=None, max_length=200)
    model_version_id: str | None = None
    training_consent: bool | None = None


class SendMessage(BaseModel):
    content: str = Field(min_length=1, max_length=20000)
    model_version_id: str | None = None
    temperature: float = Field(default=0.7, ge=0.0, le=1.5)
    max_new_tokens: int | None = Field(default=None, ge=16, le=2048)


class GenOptions(BaseModel):
    model_version_id: str | None = None
    temperature: float = Field(default=0.7, ge=0.0, le=1.5)
    max_new_tokens: int | None = Field(default=None, ge=16, le=2048)


class EditMessage(GenOptions):
    content: str = Field(min_length=1, max_length=20000)


class Feedback(BaseModel):
    value: int = Field(ge=-1, le=1)


def conv_dict(c: Conversation, preview: str | None = None) -> dict:
    return {"id": c.id, "title": c.title, "created_at": iso(c.created_at), "updated_at": iso(c.updated_at),
            "model_version_id": c.model_version_id, "training_consent": c.training_consent, "preview": preview}


def msg_dict(m: Message) -> dict:
    return {"id": m.id, "role": m.role, "content": m.content, "status": m.status, "seq": m.seq,
            "model_version_id": m.model_version_id, "feedback": m.feedback, "stats": m.stats,
            "created_at": iso(m.created_at)}


def _get_conv(s: Session, cid: str) -> Conversation:
    c = s.get(Conversation, cid)
    if c is None:
        raise HTTPException(404, "Unterhaltung nicht gefunden")
    return c


def _resolve_version(s: Session, requested: str | None, conv: Conversation | None) -> ModelVersion:
    vid = requested or (conv.model_version_id if conv else None) or registry.active_version_id(s)
    v = s.get(ModelVersion, vid)
    if v is None:
        raise HTTPException(400, "Unbekannte Modellversion")
    if v.status not in registry.CHAT_STATUSES:
        raise HTTPException(400, f"Version {vid} ist nicht freigegeben (Status {v.status}).")
    return v


def _require_engine() -> None:
    eng = get_engine()
    if eng.status != "ready":
        detail = {"loading": "Das Modell wird noch geladen – bitte kurz warten.",
                  "error": f"Modell konnte nicht geladen werden: {eng.error}",
                  "disabled": "Das Sprachmodell ist deaktiviert (RUBINE_LOAD_MODEL_ON_STARTUP=false).",
                  "idle": "Das Sprachmodell ist nicht geladen."}.get(eng.status, "Modell nicht verfügbar")
        raise HTTPException(503, detail)


def _history(s: Session, cid: str) -> list[dict]:
    msgs = s.scalars(select(Message).where(Message.conversation_id == cid, Message.status != "error")
                     .order_by(Message.seq))
    return [{"role": m.role, "content": m.content} for m in msgs if m.content]


def _next_seq(s: Session, cid: str) -> int:
    return int(s.scalar(select(func.coalesce(func.max(Message.seq), 0)).where(Message.conversation_id == cid))) + 1


def _sse(event: str, data: dict) -> str:
    return f"event: {event}\ndata: {json.dumps(data, ensure_ascii=False)}\n\n"


async def _stream_reply(request: Request, cid: str, version: ModelVersion, opts: GenOptions,
                        user_msg_id: str | None) -> AsyncIterator[str]:
    """Create an assistant message and stream tokens from the model into it."""
    with session_scope() as s:
        history = _history(s, cid)
        am = Message(conversation_id=cid, seq=_next_seq(s, cid), role="assistant", content="", status="streaming",
                     model_version_id=version.id)
        s.add(am)
        s.flush()
        aid = am.id
    loop = asyncio.get_running_loop()
    queue: asyncio.Queue[tuple[str, object]] = asyncio.Queue()
    stop = threading.Event()
    eng = get_engine()

    def worker() -> None:
        try:
            for chunk in eng.stream(history, version_id=version.id, adapter_path=version.adapter_path,
                                    max_new_tokens=opts.max_new_tokens, temperature=opts.temperature,
                                    stop_event=stop):
                loop.call_soon_threadsafe(queue.put_nowait, ("token", chunk))
            loop.call_soon_threadsafe(queue.put_nowait, ("done", None))
        except EngineUnavailable as e:
            loop.call_soon_threadsafe(queue.put_nowait, ("error", str(e)))
        except Exception as e:  # noqa: BLE001
            loop.call_soon_threadsafe(queue.put_nowait, ("error", f"{type(e).__name__}: {e}"))

    threading.Thread(target=worker, daemon=True, name="rubine-chat-stream").start()
    text, status, t0, error = "", "streaming", time.time(), None
    try:
        yield _sse("meta", {"assistant_message_id": aid, "user_message_id": user_msg_id, "model_version_id": version.id})
        while True:
            try:
                kind, val = await asyncio.wait_for(queue.get(), timeout=15)
            except asyncio.TimeoutError:
                yield ": keep-alive\n\n"
                if await request.is_disconnected():
                    status = "stopped"
                    break
                continue
            if kind == "token":
                text += str(val)
                yield _sse("token", {"t": val})
            elif kind == "done":
                status = "complete"
                break
            else:
                status, error = "error", str(val)
                break
    finally:
        stop.set()
        if status == "streaming":
            status = "stopped"
        stats = None
        if eng.last_stats and status == "complete":
            stats = {"tokens": eng.last_stats.tokens, "seconds": round(eng.last_stats.seconds, 2),
                     "tok_per_s": round(eng.last_stats.tok_per_s, 2), "prompt_tokens": eng.last_stats.prompt_tokens}
        with session_scope() as s:
            m = s.get(Message, aid)
            if m is not None:
                m.content, m.status, m.stats = (text if status != "error" else (text or "")), status, stats
                if error:
                    m.stats = {"error": error}
            c = s.get(Conversation, cid)
            if c is not None:
                c.updated_at = utcnow()
    if status == "error":
        yield _sse("error", {"message": error})
    else:
        yield _sse("done", {"status": status, "stats": stats})


def _streaming(gen: AsyncIterator[str]) -> StreamingResponse:
    return StreamingResponse(gen, media_type="text/event-stream",
                             headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})


# ------------------------------------------------------------------ routes
@router.get("/conversations")
def list_conversations(s: Session = Depends(get_db)) -> list[dict]:
    convs = s.scalars(select(Conversation).order_by(Conversation.updated_at.desc()).limit(500))
    out = []
    for c in convs:
        last = s.scalars(select(Message.content).where(Message.conversation_id == c.id)
                         .order_by(Message.seq.desc()).limit(1)).first()
        out.append(conv_dict(c, (last or "")[:120]))
    return out


@router.post("/conversations")
def create_conversation(body: NewConversation, s: Session = Depends(get_db)) -> dict:
    if body.model_version_id:
        _resolve_version(s, body.model_version_id, None)
    c = Conversation(title=(body.title or "Neuer Chat").strip() or "Neuer Chat", model_version_id=body.model_version_id)
    s.add(c)
    s.flush()
    return conv_dict(c)


@router.get("/conversations/{cid}")
def get_conversation(cid: str, s: Session = Depends(get_db)) -> dict:
    c = _get_conv(s, cid)
    msgs = s.scalars(select(Message).where(Message.conversation_id == cid).order_by(Message.seq))
    return {**conv_dict(c), "messages": [msg_dict(m) for m in msgs]}


@router.patch("/conversations/{cid}")
def patch_conversation(cid: str, body: PatchConversation, s: Session = Depends(get_db)) -> dict:
    c = _get_conv(s, cid)
    if body.title is not None:
        c.title = body.title.strip()[:200] or c.title
    if body.model_version_id is not None:
        c.model_version_id = _resolve_version(s, body.model_version_id, None).id
    if body.training_consent is not None:
        c.training_consent = body.training_consent
        if not body.training_consent:  # withdrawing consent removes pool examples from this chat
            s.execute(delete(Example).where(Example.source == "user_chat",
                                            Example.meta["conversation_id"].as_string() == cid))
    return conv_dict(c)


@router.delete("/conversations/{cid}")
def delete_conversation(cid: str, s: Session = Depends(get_db)) -> dict:
    c = _get_conv(s, cid)
    s.execute(delete(Example).where(Example.source == "user_chat", Example.meta["conversation_id"].as_string() == cid))
    s.execute(delete(Message).where(Message.conversation_id == cid))
    s.delete(c)
    return {"ok": True}


@router.post("/conversations/{cid}/messages")
async def send_message(cid: str, body: SendMessage, request: Request) -> StreamingResponse:
    with session_scope() as s:
        c = _get_conv(s, cid)
        version = _resolve_version(s, body.model_version_id, c)
        _require_engine()
        um = Message(conversation_id=cid, seq=_next_seq(s, cid), role="user", content=body.content.strip())
        s.add(um)
        if c.title == "Neuer Chat":
            first = " ".join(body.content.split())
            c.title = (first[:48] + "…") if len(first) > 48 else first
        c.updated_at = utcnow()
        s.flush()
        uid = um.id
        s.expunge(version)
    return _streaming(_stream_reply(request, cid, version, body, uid))


@router.post("/conversations/{cid}/regenerate")
async def regenerate(cid: str, body: GenOptions, request: Request) -> StreamingResponse:
    with session_scope() as s:
        c = _get_conv(s, cid)
        version = _resolve_version(s, body.model_version_id, c)
        _require_engine()
        last_user = s.scalars(select(Message).where(Message.conversation_id == cid, Message.role == "user")
                              .order_by(Message.seq.desc()).limit(1)).first()
        if last_user is None:
            raise HTTPException(400, "Keine Nutzernachricht zum Neugenerieren")
        s.execute(delete(Message).where(Message.conversation_id == cid, Message.seq > last_user.seq))
        uid = last_user.id
        s.expunge(version)
    return _streaming(_stream_reply(request, cid, version, body, uid))


@router.post("/messages/{mid}/edit")
async def edit_message(mid: str, body: EditMessage, request: Request) -> StreamingResponse:
    with session_scope() as s:
        m = s.get(Message, mid)
        if m is None or m.role != "user":
            raise HTTPException(404, "Nutzernachricht nicht gefunden")
        c = _get_conv(s, m.conversation_id)
        version = _resolve_version(s, body.model_version_id, c)
        _require_engine()
        m.content = body.content.strip()
        s.execute(delete(Message).where(Message.conversation_id == m.conversation_id, Message.seq > m.seq))
        cid, uid = m.conversation_id, m.id
        s.expunge(version)
    return _streaming(_stream_reply(request, cid, version, body, uid))


@router.post("/messages/{mid}/feedback")
def feedback(mid: str, body: Feedback, s: Session = Depends(get_db)) -> dict:
    m = s.get(Message, mid)
    if m is None or m.role != "assistant":
        raise HTTPException(404, "Antwort nicht gefunden")
    m.feedback = body.value
    c = _get_conv(s, m.conversation_id)
    proposed = False
    # Only with explicit consent, and only as *pending* (needs review in the AI Lab).
    if body.value == 1 and c.training_consent and m.status == "complete":
        prev = s.scalars(select(Message).where(Message.conversation_id == c.id, Message.seq < m.seq)
                         .order_by(Message.seq)).all()
        msgs = [{"role": x.role, "content": x.content} for x in prev if x.content][-6:]
        while msgs and msgs[0]["role"] != "user":
            msgs = msgs[1:]
        if msgs and msgs[-1]["role"] == "user":
            try:
                proposed = data_mod.add_example(s, messages=msgs, response=m.content, source="user_chat",
                                                status="pending", meta={"conversation_id": c.id, "message_id": m.id}
                                                ) is not None
            except data_mod.DataError:
                proposed = False
    return {"ok": True, "proposed_for_training": proposed}


@router.get("/search")
def search(q: str, s: Session = Depends(get_db)) -> list[dict]:
    q = q.strip()
    if len(q) < 2:
        return []
    like = f"%{q.replace('%', '').replace('_', '')}%"
    hits = s.execute(select(Conversation, Message.content).outerjoin(Message, Message.conversation_id == Conversation.id)
                     .where(or_(Conversation.title.ilike(like), Message.content.ilike(like)))
                     .order_by(Conversation.updated_at.desc()).limit(200)).all()
    seen: dict[str, dict] = {}
    for c, content in hits:
        if c.id in seen:
            continue
        snippet = None
        if content and q.lower() in content.lower():
            i = content.lower().index(q.lower())
            snippet = ("…" if i > 40 else "") + content[max(0, i - 40): i + 80] + "…"
        seen[c.id] = conv_dict(c, snippet)
    return list(seen.values())[:50]


models_router = APIRouter(prefix="/api/models", dependencies=[Depends(require_auth)])


@models_router.get("")
def list_models(s: Session = Depends(get_db)) -> dict:
    active = registry.active_version_id(s)
    versions = s.scalars(select(ModelVersion).order_by(ModelVersion.created_at))
    return {"active": active, "engine": get_engine().info(),
            "versions": [{"id": v.id, "name": v.name, "status": v.status, "chat_allowed": v.status in registry.CHAT_STATUSES,
                          "active": v.id == active, "created_at": iso(v.created_at),
                          "accuracy": ((v.metrics or {}).get("eval") or {}).get("accuracy")} for v in versions]}
